import{_ as n,l as o,o as e,c as l,v as t,p as s,x as r,d as h,i as m,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"蒙特卡洛路径","description":"","frontmatter":{"title":"蒙特卡洛路径","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mc-paths.md","filePath":"quant/mc-paths.md","lastUpdated":1789023840000}'),d={name:"quant/mc-paths.md"};function p(c,a,u,_,B,A){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="蒙特卡洛路径" tabindex="-1">蒙特卡洛路径 <a class="header-anchor" href="#蒙特卡洛路径" aria-label="Permalink to &quot;蒙特卡洛路径&quot;">​</a></h1><div class="epigraph"><p>风险中性价格是期望。用独立路径的样本均值去估这个期望：先按 SDE 造 $\\{S^{(n)}\\}$，再平均贴现支付。</p><footer>—— 据 Glasserman, Monte Carlo Methods in Financial Engineering, 2003, 第 1–3 章；Shreve, Stochastic Calculus for Finance II, 第 5 章整理</footer></div><p>上一课<a href="/quant/american-optimal-stop">美式提前行权与最优停</a>把价格写成停时上的上确界。欧式则仍是普通期望。缺口是计算：PDE 在三维以上或路径依赖时迅速失效。本课只给路径模拟接口——从 SDE 到样本均值、偏差与方差的分解——不把方差缩减做完，那是下一课。本课程是定价数学，不是权重量化，也不在这里写限价簿撮合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(V=\\mathbb E_Q[\\mathrm e^{-rT}g(S_{0:T})]\\)。若能抽样与 \\(Q\\) 一致的路径，大数定律给出 \\(\\bar V_N\\to V\\)。缺口是：抽样必须对准<a href="/quant/sde-meaning">随机微分方程的含义</a>里的积分方程，而不是随便画折线。GBM 有精确转移；一般 SDE 用 Euler–Maruyama 或 Milstein，离散步长 \\(h\\) 带来弱误差 \\(O(h)\\)（Euler）。统计误差另算：方差 \\(\\mathrm{Var}(\\xi)/N\\)，与步长无关。两条误差不能互相拿来当对方的诊断。</p><p>路径依赖（亚式、障碍监控）把 \\(g\\) 写成整条离散路径的函数；监控网格必须与合约定义一致，否则估错的是另一个支付。</p><h3 id="蒙特卡洛不是「在-下用历史轨迹重放」" tabindex="-1">蒙特卡洛不是「在 \\(P\\) 下用历史轨迹重放」 <a class="header-anchor" href="#蒙特卡洛不是「在-下用历史轨迹重放」" aria-label="Permalink to &quot;蒙特卡洛不是「在 $P$ 下用历史轨迹重放」&quot;">​</a></h3><p>历史只有一条路径，是 \\(P\\) 的实现。定价要的是 \\(Q\\) 下的集合平均。把过去十年股价当 \\(N=1\\) 的样本，没有 \\(\\mu\\mapsto r\\) 的 Girsanov，估的不是期权价。回测与定价共用「路径」一词，对象不同。</p><p><span class="marginnote">弱收敛管期望的偏差；强收敛管路径与真解的距离。定价通常只需弱阶。对冲若沿同一条 \\(W\\) 比较，才对强解敏感。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算法：抽 \\(Z\\sim N(0,I)\\)；对 GBM 用精确指数映射（几何布朗运动课已写）；否则 \\(X_{k+1}=X_k+\\mu h+\\sigma\\sqrt{h}Z_k\\)。支付 \\(\\xi^{(n)}=\\mathrm e^{-rT}g(X^{(n)})\\)，\\(\\hat V=N^{-1}\\sum\\xi^{(n)}\\)。标准误差 \\(\\sqrt{s^2/N}\\)。随机 \\(r\\) 用 \\(\\exp(-\\sum r_k h)\\) 沿路径贴现，或在 \\(Q^T\\) 下模拟远期。跳：在步内先抽泊松次数再抽跳幅。美式：不能只平均 \\(g(S_T)\\)，要在路径上估继续值（Longstaff–Schwartz 是后课可用的名字，本课不实现）。</p>',11)),(e(),s(E,null,{default:r(()=>[m(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22Q%20%E4%B8%8B%20SDE%22%5D%20--%3E%20SIM%5B%22%E7%A6%BB%E6%95%A3%E8%B7%AF%E5%BE%84%22%5D%0A%20%20SIM%20--%3E%20PAY%5B%22%E8%B4%B4%E7%8E%B0%E6%94%AF%E4%BB%98%22%5D%0A%20%20PAY%20--%3E%20AVG%5B%22%E6%A0%B7%E6%9C%AC%E5%9D%87%E5%80%BC%22%5D%0A%20%20AVG%20--%3E%20SE%5B%22%E6%A0%87%E5%87%86%E8%AF%AF%E5%B7%AE%201%20%E6%AF%94%E6%A0%B9%E5%8F%B7%20N%22%5D%0A%20%20AVG%20--%3E%20VR%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E7%BC%A9%E6%96%B9%E5%B7%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无偏（或弱阶控制的偏差）加独立同分布，中心极限定理给置信区间。瓶颈几乎总是 \\(\\mathrm{Var}(\\xi)\\)：深度虚值使多数路径贡献零，有效样本远小于 \\(N\\)。这不是随机数质量问题，是测度与支付不匹配——下一课用对偶、控制变量、重要性采样改这个方差。伪随机与拟随机（Sobol）改收敛速率，仍建立在同一路径对象上。步长 \\(h\\) 与 \\(N\\) 要配套：把 \\(N\\) 加大而 \\(h\\) 粗，会看到标准误下降、点估计却钉在错误的离散价格上。</p><p>种子与独立流：对冲差 \\(\\hat V(S+\\epsilon)-\\hat V(S)\\) 必须共用随机数，否则差分被独立噪声淹没。这是路径层的接口，不是新的定价理论。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GPU 实现，不比较生成器。不把 MC 用于估计限价簿队列。后课默认：欧式期望可用路径均值；误差报标准误；GBM 用精确格式。报价格不报标准误，等于没有完成模拟。下一课<a href="/quant/variance-reduction">方差缩减</a>在同一批路径对象上降低 \\(\\mathrm{Var}(\\xi)\\)。加路径之前先问方差。本课程随后进入财务报表，不再加定价模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MC 估 \\(Q\\) 下贴现支付的期望，不是重放历史。</li><li>离散偏差与 \\(1/\\sqrt{N}\\) 统计误差要分开。</li><li>GBM 用精确指数映射；一般 SDE 用弱阶格式。</li><li>美式还要估继续值，不能只平均终端支付。</li><li>对冲差分必须共用同一条随机数。</li><li>出处：Glasserman, Monte Carlo Methods in Financial Engineering。</li></ul>',7))])}const q=n(d,[["render",p]]);export{f as __pageData,q as default};
